import { constants } from 'node:fs';
import { lstat, open } from 'node:fs/promises';
import { canonicalCachePath } from './managed-cache-files';
import { sameNativeIdentity, sameNativeObservation } from './managed-native-identity';

/** Remove only the exact line generated by prior Skaro releases; preserve every other byte. */
export const unrestrictedBuilderPolicy = (policy: string) =>
  policy.replace(/^  max-parallelism = 1\r?\n/gm, '');

/** Compare-and-write through the same verified regular-file handle under the caller's exclusive fence. */
export async function migrateBuilderPolicy(
  root: string,
  path: string,
  before: string,
  onEffect: () => void,
) {
  const after = unrestrictedBuilderPolicy(before);
  if (after === before) return after;
  await canonicalCachePath(root, path);
  const file = await open(path, constants.O_RDWR | (constants.O_NOFOLLOW ?? 0));
  try {
    const identity = await file.stat({ bigint: true });
    if (
      !identity.isFile() ||
      identity.nlink !== 1n ||
      identity.size > 8192n ||
      (await file.readFile()).toString('utf8') !== before
    )
      throw new Error('managed_buildkit_policy_migration_source_changed');
    await canonicalCachePath(root, path);
    if (
      !sameNativeIdentity(identity, await lstat(path, { bigint: true })) ||
      !sameNativeObservation(identity, await file.stat({ bigint: true }))
    )
      throw new Error('managed_buildkit_policy_migration_source_changed');
    const bytes = Buffer.from(after);
    let offset = 0;
    while (offset < bytes.length) {
      onEffect();
      const { bytesWritten } = await file.write(bytes, offset, bytes.length - offset, offset);
      if (!bytesWritten) throw new Error('managed_buildkit_policy_migration_write_incomplete');
      offset += bytesWritten;
    }
    onEffect();
    await file.truncate(bytes.length);
    await file.sync();
    return after;
  } finally {
    await file.close();
  }
}
